-- Loads the synthetic CSV data into COST_DATA tables. Run after creating the tables.
-- Safe to re-run: each table is emptied first.

DELETE FROM COST_DATA.DIM_COST_CENTER;

DELETE FROM COST_DATA.DIM_VENDOR;

DELETE FROM COST_DATA.DIM_PROJECT;

DELETE FROM COST_DATA.FACT_COST;

DELETE FROM COST_DATA.FACT_CAPEX_STATUS;

DELETE FROM COST_DATA.FACT_PR_PO;

SELECT 'DIM_COST_CENTER' AS T, COUNT(*) AS N FROM COST_DATA.DIM_COST_CENTER UNION ALL
SELECT 'DIM_VENDOR', COUNT(*) FROM COST_DATA.DIM_VENDOR UNION ALL
SELECT 'DIM_PROJECT', COUNT(*) FROM COST_DATA.DIM_PROJECT UNION ALL
SELECT 'FACT_COST', COUNT(*) FROM COST_DATA.FACT_COST UNION ALL
SELECT 'FACT_CAPEX_STATUS', COUNT(*) FROM COST_DATA.FACT_CAPEX_STATUS UNION ALL
SELECT 'FACT_PR_PO', COUNT(*) FROM COST_DATA.FACT_PR_PO;
